void enqueue_event_write(const struct client *);

/*
 * Reserve len contiguous bytes at the tail of the client write buffer and
 * return a pointer to the reserved area, or NULL when the record does not
 * fit into the max_request_size allocation backing c->wbuf.
 */
unsigned char *client_wbuf_reserve(struct client *, size_t);

/*
 * Reserve len contiguous bytes in the client write buffer and return a
 * pointer to the reserved area, or NULL when the record would not fit.
 *
 * c->wbuf is allocated with exactly conf->max_request_size bytes in
 * client_init(), so every producer of outbound bytes has to reserve space
 * through this helper instead of writing at c->wbuf + c->towrite directly.
 * On overflow the record is dropped and logged rather than written past the
 * end of the allocation, and towrite is only advanced when the space was
 * really reserved, so write_data() can never send bytes past the buffer.
 */
unsigned char *client_wbuf_reserve(struct client *c, size_t len)
{
    size_t used  = 0;
    size_t limit = conf->max_request_size;

    if (!c || !c->wbuf)
        return NULL;

    used = c->towrite;
    if (used > limit || len > limit - used) {
        log_error("Write buffer full for %s, dropping %zu bytes (%zu/%zu)",
                  c->client_id, len, used, limit);
        return NULL;
    }

    c->towrite = used + len;

    return c->wbuf + used;
}

