/*
 * Tell whether a packet type may legitimately be received from a client.
 * CONNACK, SUBACK, UNSUBACK and PINGRESP only ever travel server -> client and
 * the 0 and 15 opcodes are reserved, so a broker must never act on them.
 */
int mqtt_opcode_is_client_packet(u8 type)
{
    switch (type) {
    case CONNECT:
    case PUBLISH:
    case PUBACK:
    case PUBREC:
    case PUBREL:
    case PUBCOMP:
    case SUBSCRIBE:
    case UNSUBSCRIBE:
    case PINGREQ:
    case DISCONNECT:
        return 1;
    default:
        return 0;
    }
}

/*
 * Main unpacking function entry point. Call the correct unpacking function
 * through a dispatch table
 */
int mqtt_unpack(u8 *buf, struct mqtt_packet *pkt, u8 byte, usize len)
{
    u8 type = byte >> 4;

    pkt->header = (union mqtt_header){.byte = byte};

    /* Reject reserved opcodes and the server -> client only packet types */
    if (!mqtt_opcode_is_client_packet(type))
        return -MQTT_ERR;

    /* PINGREQ and DISCONNECT have no variable header nor payload */
    if (type == PINGREQ || type == DISCONNECT)
        return MQTT_OK;

    /* Bound the table lookup before calling through the selected slot */
    if (type >= MQTT_PACKET_TYPES || unpack_handlers[type] == NULL)
        return -MQTT_ERR;

    return unpack_handlers[type](buf, pkt, len);
}

