static int unpack_mqtt_subscribe(u8 *buf, struct mqtt_packet *pkt, usize len)
{

    struct mqtt_subscribe subscribe;
    subscribe.tuples = NULL;

    /*
     * The packet identifier plus at least one complete 3-tuple (2 bytes topic
     * length, the topic filter and 1 byte of qos) must be covered by the
     * length declared in the fixed header
     */
    if (len < sizeof(u16) + sizeof(u16) + sizeof(u8))
        return -MQTT_ERR;

    /* Read packet id */
    subscribe.pkt_id = unpack_integer(&buf, 'H');
    len -= sizeof(u16);

    /*
     * Read in a loop all remaining bytes specified by len of the Fixed Header.
     * From now on the payload consists of 3-tuples formed by:
     *  - topic length
     *  - topic filter (string)
     *  - qos
     */
    usize i = 0;
    for (; len > 0; ++i) {

        /*
         * A tuple needs at least its 2 bytes topic length plus 1 byte of qos,
         * a shorter remainder means the declared length does not match the
         * bytes actually available: stop before the subtraction below wraps
         */
        if (len < sizeof(u16) + sizeof(u8))
            goto err;

        /*
         * The tuple counter is stored on 2 bytes, a longer list would be
         * silently truncated
         */
        if (i == UINT16_MAX)
            goto err;

        /* Read length bytes of the first topic filter */
        len -= sizeof(u16);

        /* We have to make room for additional incoming tuples */
        subscribe.tuples =
            try_realloc(subscribe.tuples, (i + 1) * sizeof(*subscribe.tuples));
        subscribe.tuples[i].topic_len =
            unpack_string16(&buf, &subscribe.tuples[i].topic);

        if (!subscribe.tuples[i].topic)
            goto err;

        /*
         * The topic length is declared by the client itself, it must fit in
         * what is left of the packet, otherwise the subtraction below wraps
         */
        if (subscribe.tuples[i].topic_len > len) {
            free_memory(subscribe.tuples[i].topic);
            goto err;
        }

        len -= subscribe.tuples[i].topic_len;
        subscribe.tuples[i].qos = unpack_integer(&buf, 'B');
        len -= sizeof(u8);
    }

    subscribe.tuples_len = i;
    pkt->subscribe       = subscribe;

    return MQTT_OK;

err:
    /* Release the tuples decoded so far, no one else references them */
    for (usize k = 0; k < i; ++k)
        free_memory(subscribe.tuples[k].topic);
    free_memory(subscribe.tuples);
    return -MQTT_ERR;
}

