usize mqtt_decode_length(u8 *buf, usize buflen, unsigned *pos)
{

    u8 c;
    u64 multiplier = 1LL;
    u64 value      = 0LL;
    *pos           = 0;

    do {
        /*
         * Never consume a length byte that was not received or that would go
         * past the 4 bytes the standard allows to encode the length
         */
        if (*pos == MAX_LEN_BYTES || *pos == buflen)
            return (usize) -1;

        c = *buf;
        value += (c & 127) * multiplier;
        multiplier *= 128;
        ++buf;
        ++(*pos);
